    private boolean graphsEqual(Node a, Node b) {

        Map<Integer, Set<Integer>> adjA = adjacency(a);
        Map<Integer, Set<Integer>> adjB = adjacency(b);
        return adjA.equals(adjB);
    }

    private Map<Integer, Set<Integer>> adjacency(Node start) {

        Map<Integer, Set<Integer>> result = new HashMap<>();
        Set<Integer> visited = new HashSet<>();
        List<Node> queue = new ArrayList<>();
        queue.add(start);
        visited.add(start.val);

        while (!queue.isEmpty()) {
            Node node = queue.remove(0);
            Set<Integer> neighbors = new HashSet<>();
            for (Node neighbor : node.neighbors) {
                neighbors.add(neighbor.val);
                if (visited.add(neighbor.val)) {
                    queue.add(neighbor);
                }
            }
            result.put(node.val, neighbors);
        }

        return result;
    }

    private boolean allNodesDistinct(Node original, Node cloned) {

        Set<Node> originalNodes = collect(original);
        Set<Node> clonedNodes = collect(cloned);

        for (Node node : originalNodes) {
            if (clonedNodes.contains(node)) {
                return false;
            }
        }

        return true;
    }

    private Set<Node> collect(Node start) {

        Set<Node> nodes = new HashSet<>();
        List<Node> queue = new ArrayList<>();
        queue.add(start);
        nodes.add(start);

        while (!queue.isEmpty()) {
            Node node = queue.remove(0);
            for (Node neighbor : node.neighbors) {
                if (nodes.add(neighbor)) {
                    queue.add(neighbor);
                }
            }
        }

        return nodes;
    }
